from pydantic import BaseModel, Field


# ============================================================
# CREATE ADMISSION
# ============================================================

class AdmissionCreate(BaseModel):

    # Generated by the backend.
    # Frontend does not provide admission_id.

    patient_id: str

    admit_type: str

    ward_type: str

    discharge_type: str

    los_days: int = Field(
        ...,
        ge=0,
    )

    num_procedures: int = Field(
        default=0,
        ge=0,
    )

    charlson_index: int = Field(
        default=0,
        ge=0,
    )

    hba1c: float = Field(
        ...,
        ge=0,
    )

    creatinine: float = Field(
        ...,
        ge=0,
    )

    haemoglobin: float = Field(
        ...,
        ge=0,
    )

    systolic_bp: int = Field(
        ...,
        ge=0,
    )


# ============================================================
# UPDATE ADMISSION
# ============================================================

class AdmissionUpdate(BaseModel):
    admit_type: str | None = None
    ward_type: str | None = None
    discharge_type: str | None = None
    los_days: int | None = Field(default=None, ge=0)
    num_procedures: int | None = Field(default=None, ge=0)
    charlson_index: int | None = Field(default=None, ge=0)
    hba1c: float | None = Field(default=None, ge=0)
    creatinine: float | None = Field(default=None, ge=0)
    haemoglobin: float | None = Field(default=None, ge=0)
    systolic_bp: int | None = Field(default=None, ge=0)


# ============================================================
# ADMISSION RESPONSE
# ============================================================


class AdmissionResponse(BaseModel):

    id: int

    admission_id: str

    patient_id: int

    admit_type: str

    ward_type: str

    discharge_type: str

    los_days: int

    num_procedures: int

    charlson_index: int

    hba1c: float

    creatinine: float

    haemoglobin: float

    systolic_bp: int

    class Config:
        from_attributes = True